using System.ComponentModel; //watashi wa watashi sore dake
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Windows.Forms;
namespace ZenForms.Core { [Category("ZenForms Modern Controls")] public class ZenProgressBar:Control { private int value; [Category("ZenForms Data")] public int Value{get{return value;}set{this.value=value<0?0:value>100?100:value;Invalidate();}} [DefaultValue(false)] public bool ShowPercentage{get;set;} public ZenProgressBar(){Height=18;Size=new Size(240,18);SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.ResizeRedraw,true);} protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;Rectangle r=new Rectangle(0,2,Width-1,Height-5);using(GraphicsPath bg=ZenButtonBase.RoundPath(r,8))using(SolidBrush b=new SolidBrush(ZenTheme.SurfaceRaised))e.Graphics.FillPath(b,bg);if(Value>0){Rectangle f=new Rectangle(0,2,System.Math.Max(1,r.Width*Value/100),r.Height);using(GraphicsPath p=ZenButtonBase.RoundPath(f,8))using(LinearGradientBrush g=new LinearGradientBrush(f,ZenTheme.Primary,ZenTheme.Accent,0f))e.Graphics.FillPath(g,p);}if(ShowPercentage)TextRenderer.DrawText(e.Graphics,Value+"%",Font,ClientRectangle,ZenTheme.Foreground,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);} } }